function ownerRecord(id,L){return L?.records?.find?.(r=>r?.logistics?.id===id)?.id||''}
function add(P,id,name,branch,kind,a){let p=P.get(id);if(!p){p={personId:id,name,branch,kind,assignments:[],nodes:[],records:[]};P.set(id,p)}p.assignments.push(Object.freeze(a));p.nodes.push(...(a.nodeIds||[]));if(a.relatedRecordId)p.records.push(a.relatedRecordId);if(a.ownerRecordId)p.records.push(a.ownerRecordId)}
