function baseOutcomesForRaw(p,L,H){const a=[...p.assignments].sort((x,y)=>y.startYearsBeforePresent-x.startYearsBeforePresent),out=[];for(const as of a){if(as.shipRegistry){const s=L?.REGISTERED_SHIPS?.find(x=>x.registry===as.shipRegistry);if(s){const ev=(H?.historyFor?.(s,L)?.events||[]).filter(e=>significant(e)&&inAssignment(e,as)).sort((x,y)=>y.yearsBeforePresent-x.yearsBeforePresent);let kept=0;for(const e of ev){const o=eventOutcome(p.personId,as,e,s);if(o){out.push(o);if(++kept>=2)break}}}}}for(let i=0;i<a.length-1;i++){const older=a[i],newer=a[i+1];if(older.endYearsBeforePresent===newer.startYearsBeforePresent){const o=boundaryOutcome(p.personId,older,newer);if(o)out.push(o)}}const active=a.some(x=>x.endYearsBeforePresent===0),newest=a.at(-1);if(!active){const o=finalOutcome(p.personId,newest,p.branch,Math.max(0,careerStart(a)-careerEnd(a)));if(o)out.push(o)}return Object.freeze(out.sort((x,y)=>y.yearsBeforePresent-x.yearsBeforePresent||x.outcomeId.localeCompare(y.outcomeId)))}

